// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    // Fuzz the caller (from) and a boolean that decides whether the helper should revert.
    function testFuzz_property(address from, bool shouldRevert) public {
        // keep from non-zero to be a realistic actor
        vm.assume(from != address(0));

        // Prepare inputs: single-element _tos and v arrays so exactly one external call is made.
        address[] memory tos = new address[](1);
        uint256[] memory vals = new uint256[](1);

        // Deploy a helper that either reverts or accepts, controlled by shouldRevert
        ReverterOrRecorder helper = new ReverterOrRecorder(shouldRevert);
        tos[0] = address(helper);
        vals[0] = 123;

        // Call and observe whether transfer reverts. Reference C should revert when helper reverts,
        // mutant returns true early and will not revert. We assert that when helper is set to revert,
        // c.transfer must revert (ok == false). This is the single assertion.
        bool ok;
        try c.transfer(from, address(helper), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ALL inputs, if the callee will revert (shouldRevert == true)
        // then c.transfer(...) MUST revert (ok == false). The buggy mutant that returns true early
        // will break this for shouldRevert == true.
        if (shouldRevert) {
            assertTrue(!ok);
        } else {
            // when helper does not revert, both should succeed; still assert success to keep the property
            assertTrue(ok);
        }
    }
}

// Helper that either reverts on the expected selector or records calls (but here we only need revert behavior)
contract ReverterOrRecorder {
    bool public shouldRevert;
    event Called(address from, address to, uint256 amount);
    constructor(bool _shouldRevert) { shouldRevert = _shouldRevert; }

    // Match the selector transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 amount) external {
        if (shouldRevert) revert("revert on purpose");
        emit Called(from, to, amount);
    }

    // Fallback to catch raw calls (not strictly necessary but harmless)
    fallback() external payable {
        if (shouldRevert) revert("revert fallback");
    }
    receive() external payable {
        if (shouldRevert) revert("revert receive");
    }
}
